// JSX
const element = <h1>Hello, World!</h1>;

// Without JSX (what JSX compiles to)
const element = React.createElement('h1', null, 'Hello, World!');

const name = 'Alice';
const element = <h1>Hello, {name}!</h1>;

// Expressions work too
const double = (n) => n * 2;
const result = <p>5 doubled is {double(5)}</p>;

// Ternary operators
const isLoggedIn = true;
const greeting = <p>{isLoggedIn ? 'Welcome back!' : 'Please log in'}</p>;

// HTML style
<div style="background-color: blue; color: white;">Hello</div>

// JSX style (camelCase property names)
<div style={{ backgroundColor: 'blue', color: 'white' }}>Hello</div>

// This is valid - single root element
return (
  <div>
    <h1>Title</h1>
    <p>Content</p>
  </div>
);

// This is also valid - using Fragment
return (
  <>
    <h1>Title</h1>
    <p>Content</p>
  </>
);
